// Loads the ls-wasm package generated by `npm run build:wasm`
// (wasm-bindgen --target web into ./pkg, gitignored).

import type { WasmApi } from "./api.ts";

let loading: Promise<WasmApi> | null = null;

/** Loads and initialises the WASM module once; later calls share the promise. */
export function loadWasm(): Promise<WasmApi> {
  loading ??= (async () => {
    const pkg = await import("./pkg/ls_wasm.js");
    await pkg.default();
    pkg.init();
    // Compile-time check that the generated bindings provide the API the client uses.
    const api: WasmApi = pkg;
    return api;
  })();
  return loading;
}
